<template>
<div class="reactivate-backdrop" @click.self="emit('close')"><section class="reactivate-window" role="dialog" aria-modal="true" aria-label="Reactivar cuenta"><header class="react-header"><div><small>GESTIÓN DE MEMBRESÍAS / RENOVACIONES</small><h2>REACTIVAR <span>CUENTA</span></h2><p>Regulariza el adeudo y confirma la renovación para habilitar el acceso.</p></div><button type="button" class="close" @click="emit('close')" aria-label="Cerrar">×</button></header><main class="react-body"><p v-if="loading" class="feedback">Consultando el adeudo real del cliente...</p><p v-if="error" class="feedback danger" role="alert">{{error}} <button type="button" @click="cargar">Reintentar</button></p><template v-if="cliente"><section class="react-card"><div class="section-head"><span>01</span><div><strong>Cuenta del cliente</strong><small>Datos registrados en la sucursal</small></div></div><div class="client-data"><strong>{{cliente.nombre}}</strong><span>{{cliente.correo||'Sin correo registrado'}}</span><div class="client-tags"><span>{{cliente.estatus_inscripcion}}</span><span>{{cliente.plan}}</span><span>Vencimiento: {{fecha(cliente.fecha_vencimiento)}}</span></div></div></section><section class="react-card"><div class="section-head"><span>02</span><div><strong>Desglose de reactivación</strong><small>Importes calculados por Laravel, sin valores de ejemplo</small></div></div><div class="breakdown"><div><span>Adeudo anterior</span><strong>{{moneda(desglose.adeudo)}}</strong></div><div><span>Recargos ya registrados</span><strong>{{moneda(desglose.recargos)}}</strong></div><div><span>Nueva membresía, cuando corresponde</span><strong>{{moneda(desglose.renovacion)}}</strong></div><div><span>Saldo a favor</span><strong>- {{moneda(desglose.saldo_a_favor)}}</strong></div></div></section><div class="total-card"><div><small>TOTAL A COBRAR</small><strong>Reactivación de membresía</strong></div><b>{{moneda(desglose.total)}}</b></div><section class="react-card"><div class="section-head"><span>03</span><div><strong>Método de pago</strong><small>El estado cambiará solo después de la respuesta del servidor</small></div></div><div v-if="desglose.total>0" class="methods"><button type="button" :class="{active:metodo==='Efectivo'}" @click="metodo='Efectivo'"><span>▣</span><strong>Efectivo</strong><small>Folio automático</small></button><button type="button" :class="{active:metodo==='Transferencia'}" @click="metodo='Transferencia'"><span>⇄</span><strong>Transferencia</strong><small>Referencia obligatoria</small></button><button type="button" disabled title="Requiere Stripe Connect"><span>▤</span><strong>Tarjeta</strong><small>Stripe pendiente de integración</small></button></div><p v-else class="info">La cuenta ya tiene cobertura pagada. Se restaurará sin generar otro cobro.</p><div v-if="desglose.total>0" class="reference"><label for="folio-re">Folio / Referencia</label><input id="folio-re" v-model.trim="referencia" :disabled="metodo!=='Transferencia'" :placeholder="metodo==='Transferencia'?'Número del comprobante':'Generado automáticamente en efectivo'" /></div></section><p v-if="saveError" role="alert" class="feedback danger">{{saveError}}</p><footer class="actions"><button type="button" class="cancel" @click="emit('close')">Cancelar</button><button type="button" class="confirm" :disabled="guardando||loading||!cliente||(desglose.total>0&&!metodo)" @click="guardar">{{guardando?'Procesando...':desglose.total>0?'Cobrar y reactivar':'Restaurar cuenta'}}</button></footer></template></main></section></div>
</template>
<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
const props=defineProps<{inscripcionId:number;sedeId:number}>();const emit=defineEmits<{(e:'close'):void;(e:'reactivated'):void}>();
type Desglose={adeudo:number;recargos:number;renovacion:number;saldo_a_favor:number;total:number};type Cliente={nombre:string;correo:string|null;plan:string;estatus_inscripcion:string;fecha_vencimiento:string|null;desglose:Desglose};
const API=String(import.meta.env.VITE_API_URL||'').replace(/\/+$/,'').replace(/\/api$/i,'');const cliente=ref<Cliente|null>(null),loading=ref(false),guardando=ref(false),error=ref(''),saveError=ref(''),metodo=ref(''),referencia=ref('');const desglose=computed<Desglose>(()=>cliente.value?.desglose||{adeudo:0,recargos:0,renovacion:0,saldo_a_favor:0,total:0});
const token=()=>{for(const st of [sessionStorage,localStorage]){for(const k of ['token','auth_token','access_token','gym_token','GYM_ACCOUNT_token','gymAccountToken']){const v=st.getItem(k);if(v)return v.replace(/^Bearer\s+/i,'');}for(const k of ['auth','user','session','gymAccount','gym_account'])try{const x=JSON.parse(st.getItem(k)||'null');if(x?.token||x?.access_token||x?.accessToken)return String(x.token||x.access_token||x.accessToken).replace(/^Bearer\s+/i,'');}catch{}}return '';};
const request=async(path:string,init:RequestInit={})=>{const t=token();if(!t)throw new Error('Inicia sesión nuevamente.');const r=await fetch(`${API}/api/gym/reactivaciones/${props.inscripcionId}${path}`,{...init,headers:{Accept:'application/json',Authorization:`Bearer ${t}`,...(init.body?{'Content-Type':'application/json'}:{}),...(init.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){const e=d.errors?Object.values(d.errors).flat().join(' '):'';throw new Error(e||d.message||`Error HTTP ${r.status}`);}return d;};
const cargar=async()=>{loading.value=true;error.value='';cliente.value=null;try{const d=await request(`?sede_id=${props.sedeId}`);cliente.value=d.cliente;}catch(e:any){error.value=e?.message||'No se pudo consultar la cuenta.';}finally{loading.value=false;}};
const guardar=async()=>{if(guardando.value||!cliente.value)return;saveError.value='';if(desglose.value.total>0&&!metodo.value){saveError.value='Selecciona un método de pago.';return;}if(metodo.value==='Transferencia'&&!referencia.value){saveError.value='La transferencia necesita su referencia.';return;}guardando.value=true;try{await request('',{method:'POST',body:JSON.stringify({sede_id:props.sedeId,monto:desglose.value.total,metodo_pago:desglose.value.total>0?metodo.value:null,referencia_pago:metodo.value==='Transferencia'?referencia.value:null})});emit('reactivated');}catch(e:any){saveError.value=e.message||'No se pudo reactivar. No se confirmó ningún pago.';}finally{guardando.value=false;}};
const moneda=(n:number)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(n)||0);const fecha=(v:string|null)=>{const m=String(v||'').match(/^(\d{4})-(\d\d)-(\d\d)/);return m?`${m[3]}/${m[2]}/${m[1]}`:'—';};onMounted(()=>void cargar());
</script>
<style scoped>
