t-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.client-tags span{border:1px solid rgba(96,165,250,.25);background:rgba(96,165,250,.08);padding:6px 10px;border-radius:20px;font-size:11px}.breakdown{display:grid;gap:12px}.breakdown>div{display:flex;justify-content:space-between;gap:15px;font-size:13px;color:#b6bac9}.breakdown strong{color:#f4f5fa;white-space:nowrap}.total-card{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:21px;border:1px solid rgba(96,165,250,.36);border-radius:15px;background:linear-gradient(115deg,rgba(24,75,183,.2),rgba(6,13,37,.3))}.total-card>div{display:flex;flex-direction:column;gap:4px}.total-card small{font-size:11px;color:var(--color-highlight,#60a5fa);font-weight:800;letter-spacing:.8px}.total-card strong{font-family:'Oswald',sans-serif;font-size:17px}.total-card b{font-size:25px;color:#34d399;white-space:nowrap}.methods{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.methods button{padding:13px 10px;min-height:92px;display:flex;align-items:flex-start;flex-direction:column;gap:6px;border-radius:13px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.02);color:#e5e7eb;text-align:left;cursor:pointer}.methods button.active{border-color:var(--color-highlight,#60a5fa);background:rgba(96,165,250,.12)}.methods button:disabled{opacity:.42;cursor:not-allowed}.methods button span{font-size:20px;color:var(--color-highlight,#60a5fa)}.methods button strong{font-size:13px}.methods button small{color:#9ca3b8;font-size:11px}.reference{display:flex;flex-direction:column;gap:9px;margin-top:17px}.reference label{font-size:12px;font-weight:700}.reference input{height:44px;border-radius:10px;background:rgba(0,0,0,.24);border:1px solid rgba(255,255,255,.15);color:#fff;padding:0 13px;outline:none}.reference input:focus{border-color:var(--color-highlight,#60a5fa)}.reference input:disabled{opacity:.55}.feedback{padding:12px;border:1px solid rgba(96,165,250,.2);border-radius:10px;font-size:13px}.danger{color:#fda4af;border-color:rgba(244,63,94,.3)}.feedback button{background:none;border:0;color:#93c5fd;cursor:pointer;text-decoration:underline}.info{color:#a7f3d0;font-size:13px}.actions{display:flex;justify-content:flex-end;gap:10px}.actions button{padding:13px 19px;border-radius:11px;font-weight:700;cursor:pointer}.cancel{color:#d1d5db;background:transparent;border:1px solid rgba(255,255,255,.18)}.confirm{color:var(--color-texto-botones,#fff);background:var(--color-botones,#2563eb);border:0}.confirm:disabled{opacity:.5;cursor:not-allowed}@media(max-width:600px){.reactivate-backdrop{align-items:flex-end;padding:0}.reactivate-window{max-height:95dvh;border-radius:18px 18px 0 0}.react-header{padding:19px}.react-body{padding:14px}.react-card{padding:16px}.methods{grid-template-columns:1fr 1fr}.methods button{min-height:84px}.total-card b{font-size:20px}.actions{flex-direction:column-reverse}.actions button{width:100%}}
</style>
